import unittest
from xml.dom import minidom

from ta_emss.utilities.SCFC_parser_lib.scfc_elements.Managed_Object_Attribute import ManagedObjectScalarAttribute, \
    ManagedObjectStructuralAttribute


class TestManagedObjectScalarAttribute(unittest.TestCase):
    def setUp(self):
        xml_doc = minidom.parse("/home/ute/Desktop/Add_cell_2.xml")
        managed_objects = xml_doc.getElementsByTagName('managedObject')
        lnbts = managed_objects[0]
        self.actDualBand = ManagedObjectScalarAttribute(lnbts.childNodes[1])

    def test_get_name(self):
        self.assertEqual(self.actDualBand.get_name(), "actDualBand")

    def test_is_scalar(self):
        self.assertTrue(self.actDualBand.is_scalar())

    def test_get_value(self):
        self.assertEqual(self.actDualBand.get_value(), "true")


class TestManagedObjectStructuralAttribute(unittest.TestCase):
    def setUp(self):
        xml_doc = minidom.parse("/home/ute/Desktop/Add_cell_2.xml")
        managed_objects = xml_doc.getElementsByTagName('managedObject')
        topf = managed_objects[4]
        lncel = managed_objects[5]
        self.sib3 = ManagedObjectStructuralAttribute(lncel.childNodes[-2])
        self.acceptedClockQuality = ManagedObjectStructuralAttribute(topf.childNodes[3])

    def test_get_name(self):
        self.assertEqual(self.sib3.get_name(), "sib3Scheduling")
        self.assertEqual(self.acceptedClockQuality.get_name(), "acceptedClockQuality")

    def test_is_scalar(self):
        self.assertFalse(self.sib3.is_scalar())
        self.assertFalse(self.acceptedClockQuality.is_scalar())

    def test_has_subattributes(self):
        self.assertTrue(self.sib3.has_subattributes())
        self.assertFalse(self.acceptedClockQuality.has_subattributes())

    def test_get_value(self):
        self.assertEqual(self.sib3.get_value(), [{"siMessageSibType": "SIB3", "siMessagePeriodicity": "80ms", "siMessageRepetition": "1"}])
        self.assertEqual(self.acceptedClockQuality.get_value(), ["6", "7", "13", "14"])


if __name__ == "__main__":
    unittest.main()
